  template: '<p>This is a shared component</p>'
})
export class SharedComponent { }
```
5. **Add the component to the shared module**: In the `shared.module.ts` file, add the `SharedComponent` to the `declarations` array.
```typescript
import { NgModule } from '@angular/core';
